shapes.code:
enum Shape {
    Rectangle { width: u32, height: u32 },
    Triangle { base: u32, height: u32 },
}

impl Shape {
    fn name(&self) -> &'static str {
        match self {
            Shape::Rectangle { .. } => "Rectangle",
            Shape::Triangle { .. } => "Triangle",
        }
    }

    fn area(&self) -> u32 {
        match self {
            Shape::Rectangle { width, height } => width * height,
            Shape::Triangle { base, height } => base * height / 2,
        }
    }
}

fn main() {
    let shapes = [
        Shape::Rectangle { width: 3, height: 4 },
        Shape::Triangle { base: 10, height: 3 },
    ];
    for s in &shapes {
        println!("{}: {}", s.name(), s.area());
    }
}

signature.code:
// Ownership: every value has one owner; borrows are checked at compile time.
fn total_len(words: &[String]) -> usize {
    words.iter().map(|w| w.len()).sum() // shared borrow: read-only
}

fn shout(words: &mut Vec<String>) {
    for w in words.iter_mut() {
        *w = w.to_uppercase(); // exclusive borrow: may mutate
    }
}

fn consume(words: Vec<String>) -> String {
    words.join("-") // takes ownership; `words` is freed on return
}

fn main() {
    let mut words = vec![String::from("own"), String::from("borrow")];
    println!("{}", total_len(&words));
    shout(&mut words);
    let joined = consume(words); // `words` is moved here...
    // println!("{:?}", words);  // ...so this line would not compile
    println!("{joined}");
}
